window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-04d80faafd746a43"]={"versions": [{"id": "FIG-04d80faafd746a43", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR VFB-Komponentendiagramm (Internal Architecture View einer <code>CompositionSwComponentType</code> auf Virtual Function Bus-Ebene).</li>\n<li><strong>Technischer Zweck:</strong> Referenzarchitektur der <code>CrsCtrlAndAcc SW-Composition</code> (Cruise Control & Adaptive Cruise Control) bei Anbindung genau eines Umfeldsensors (<code>SurrndgsSnsr</code>) über einen Complex Device Driver (CDD).</li>\n<li><strong>Systemische Einordnung:</strong> Domäne Chassis / Fahrerassistenz (AUTOSAR Chassis Application Interfaces, R4.0.3). Das Diagramm kapselt die Funktionslogik zur Längsregelung (Abstands- und Geschwindigkeitsregelung) zwischen HMI-Bedienung, Sensor-Vorverarbeitung, Fahrzeugzustandsbeobachtung und unterlagerter Längsdynamik-Aktuatorik (<code>Vlc</code> – Vehicle Longitudinal Control / <code>Esc</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### A. Kapselnde Composition</p>\n<ul class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAcc SW-Composition</code> (<code>CompositionSwComponentType</code>):</strong> Aggregiert fünf atomare Software-Components (<code>ApplicationSwComponentType</code>) zur Abbildung von CC- und ACC-Funktionen.</li>\n</ul>\n<p class=\"fig-p\">#### B. Interne atomare SW-Cs</p>\n<ol class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAccStCtrl</code> (State Control):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verwaltet Betriebsmodi (Off, Standby, Active, Override, Error/Degradation).</li>\n<li>Schnittstellen:</li>\n<li><em>R-Port (Delegation):</em> Anbindung an <code>WPII-10.5 (HMI)</code> für Fahrerbedienung (Set, Resume, Target Speed, Time Gap).</li>\n<li><em>R/P-Port (Delegation):</em> Anbindung an <code>WPII-10.1 (Body)</code> zur Abfrage von Systemfreigaben (z. B. ESC-, EPB-Status).</li>\n<li><em>P-Ports (Assembly):</em> Übergabe der Modus-/Statusvorgaben an <code>FolwCtrlAndAArbn</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>AccObjTarSeln</code> (ACC Object Target Selection):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Selektiert und verfolgt das führungsrelevante Zielobjekt (Relevant Target / In-Lane Object).</li>\n<li>Schnittstellen:</li>\n<li><em>R-Port (Assembly/Delegation):</em> Empfang vorverarbeiteter Umfelddaten von <code>SnsrDaProcGen[2]</code> aus dem CDD.</li>\n<li><em>R-Port (Assembly):</em> Empfang kinematischer Ego-Fahrzeugdaten von <code>CrsCtrlAndAccObsvrForVehSt</code>.</li>\n<li><em>P-Port (Assembly):</em> Bereitstellung von Zielobjekt-Trajektorie, Relativgeschwindigkeit ($\\Delta v$) und Distanz ($\\Delta s$) an <code>FolwCtrlAndAArbn</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAccObsvrForVehSt</code> (Observer for Vehicle State):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Filterung und Zustandsschätzung der Fahrzeugkinematik (Geschwindigkeit, Beschleunigung, Gierrate, Nickwinkel).</li>\n<li>Schnittstellen:</li>\n<li><em>R-Port (Delegation):</em> Roh-/Bussignale von <code>WPII-10.2 (Powertrain)</code> (Raddrehzahlen, ESC-, EPB-, Antriebsstrang-Rückmeldungen).</li>\n<li><em>P-Ports (Assembly):</em> Verteilung des Ego-Zustands an <code>AccObjTarSeln</code>, <code>CrsCtrlFree</code>, <code>FolwCtrlAndAArbn</code> sowie Rückführung zur Ego-Bewegungskompensation an den <code>SurrndgsSnsr</code> (CDD).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>CrsCtrlFree</code> (Cruise Control Free / Konventioneller Tempomat):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Regelstrecke für reine Geschwindigkeitsregelung ohne Abstandsführung.</li>\n<li>Schnittstellen:</li>\n<li><em>R-Port (Assembly):</em> Ist-Zustand von <code>CrsCtrlAndAccObsvrForVehSt</code>.</li>\n<li><em>P-Port (Assembly):</em> Konventionelle Beschleunigungsanforderung ($a_{\\text{req, CC}}$) an <code>FolwCtrlAndAArbn</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>FolwCtrlAndAArbn</code> (Following Control and Acceleration Arbitration):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abstandsfolgeregelung (Headway Control) und Sollwert-Arbitrierung.</li>\n<li>Arbitriert zwischen Fahrervorgabe, CC-Sollwert (<code>CrsCtrlFree</code>) und ACC-Sollwert (basierend auf <code>AccObjTarSeln</code>).</li>\n<li>Schnittstellen:</li>\n<li><em>P-Port (Delegation):</em> Konsolidierte Beschleunigungs-/Verzögerungsanforderung ($a_{\\text{req}}$, Jerk-Limits) an die externe Komponente <code>Vlc</code> (Vehicle Longitudinal Control).</li>\n</ul>\n<p class=\"fig-p\">#### C. Externe Entitäten & Boundary-Schnittstellen</p>\n<ul class=\"fig-list\">\n<li><strong><code>SurrndgsSnsr</code> (Complex Device Driver + Hardware):</strong></li>\n<li>Umfasst physischen <code>Sensor [2]</code> (z. B. Radar/Lidar/Kamera) und BSW-seitigen <code>Complex Device Driver</code> mit Ausprägung <code>SnsrDaProcGen[2]</code> (Generic Sensor Data Processing). Umgeht Standard-BSW-IO-Pfade für echtzeitkritische Punktwolken-/Objektlisten.</li>\n<li><strong><code>Vlc</code> (Vehicle Longitudinal Control) / <code>Esc</code>:</strong></li>\n<li>Unterlagerte Drehmoment- und Bremsdruck-Arbitrierungsinstanz im Fahrwerkspfad zur Ansteuerung der Aktuatoren (ESC-Bremse, Motorsteuerung/Transmission).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Datenfluss</h4>\n<ol class=\"fig-list\">\n<li><strong>Messwertaufnahme & Sensorkompensation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Sensor [2]</code> generiert Rohumfelddaten. Der CDD verarbeitet diese zyklisch (<code>SnsrDaProcGen[2]</code>).</li>\n<li><code>CrsCtrlAndAccObsvrForVehSt</code> liefert zyklisch Ego-Geschwindigkeit und Gierrate an den CDD/Sensor, um stationäre Objekte zu diskriminieren und Ego-Bewegungskompensation durchzuführen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Objektselektion:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>AccObjTarSeln</code> ordnet die vom CDD empfangene Objektliste dem prädizierten Fahrkorridor zu und bestimmt das primäre Regelobjekt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zustands- und Fahrerbedienpfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Fahrerinput über <code>WPII-10.5 (HMI)</code> triggert Zustandswechsel in <code>CrsCtrlAndAccStCtrl</code>.</li>\n<li>Bei Aktivierung signalisiert <code>CrsCtrlAndAccStCtrl</code> Freigaben und Betriebsmodi (ACC aktiv vs. CC aktiv) an <code>FolwCtrlAndAArbn</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Regelung & Arbitrierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei freier Fahrt: <code>CrsCtrlFree</code> berechnet die Führungsbeschleunigung zur Zielgeschwindigkeitsregelung.</li>\n<li>Bei Folgezustand: <code>FolwCtrlAndAArbn</code> berechnet über Zielabstand und Relativgeschwindigkeit das Soll-Beschleunigungsprofil zur Abstandsführung.</li>\n<li><code>FolwCtrlAndAArbn</code> arbitriert (Minimum-Auswahl bezüglich Abstands- vs. Tempomatanforderung) und begrenzt Ruck/Gradienten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuierungsübergabe:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der resultierende Beschleunigungswert ($a_{\\text{req}}$) wird zyklisch über den P-Port an <code>Vlc</code> ausgegeben, welches Bremsanforderungen an das <code>Esc</code> bzw. Antriebsmomente an das Motorsteuergerät delegiert.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Spezifikationsstatus (AUTOSAR_EXP_AIChassis):</strong> Als <em>Explanation</em> (EXP) handelt es sich um eine normative Empfehlung/Referenzarchitektur, nicht um feste SWS-Pflichtanforderungen. Port-Interfaces und Datentypen folgen jedoch den standardisierten AUTOSAR Application Interfaces (Blueprint-Konformität).</li>\n<li><strong>CDD-Einsatz (<code>Complex Device Driver</code>):</strong></li>\n<li>Notwendig, da AUTOSAR bis R4.0.3 keinen standardisierten BSW-Stack für komplexe Umfeldsensorik (Radar-/Kamera-Datenströme, SPI/Ethernet-Rohdaten) bereitstellt.</li>\n<li>Entwickler müssen sicherstellen, dass der CDD die definierten AUTOSAR-Port-Schnittstellen (<code>Sender-Receiver</code>) zur VFB-Schicht (<code>AccObjTarSeln</code>) exakt repliziert.</li>\n<li><strong>Komponentenschnitt:</strong></li>\n<li>Die Trennung von <code>AccObjTarSeln</code> (Objektfilterung) und <code>FolwCtrlAndAArbn</code> (Regelungsarbitrierung) ermöglicht den Sensor-Tausch (z. B. 1x Radar vs. Fusionssensor), ohne die nachgelagerte Fahrzeuglängsdynamik-Regelung anfassen zu müssen.</li>\n<li><strong>RTE- & Task-Allokation:</strong></li>\n<li><code>FolwCtrlAndAArbn</code> und <code>AccObjTarSeln</code> erfordern deterministische Abtastzeiten (typisch: 20–50 ms Task-Periodizität).</li>\n<li><code>CrsCtrlAndAccStCtrl</code> kann in einer niederprioren Zyklustask oder ereignisgesteuert (<code>DataReceivedEvent</code> von HMI) ausgeführt werden.</li>\n<li>Inter-Runnable-Variables (IRV) bzw. RTE-Puffer müssen gegen Dateninkonsistenz geschützt werden (Ego-Fahrzeugstatus muss zeitsynchron zu den Sensordaten im Regelungszyklus vorliegen).</li>\n</ul>"}, {"id": "FIG-37b13293d309d942", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR VFB-Komponentendiagramm (Internal Architecture View einer <code>CompositionSwComponentType</code> auf Virtual Function Bus-Ebene).</li>\n<li><strong>Technischer Zweck:</strong> Referenzarchitektur der <code>CrsCtrlAndAcc SW-Composition</code> (Cruise Control & Adaptive Cruise Control) bei Anbindung genau eines Umfeldsensors (<code>SurrndgsSnsr</code>) über einen Complex Device Driver (CDD).</li>\n<li><strong>Systemische Einordnung:</strong> Domäne Chassis / Fahrerassistenz (AUTOSAR Chassis Application Interfaces, R4.0.3). Das Diagramm kapselt die Funktionslogik zur Längsregelung (Abstands- und Geschwindigkeitsregelung) zwischen HMI-Bedienung, Sensor-Vorverarbeitung, Fahrzeugzustandsbeobachtung und unterlagerter Längsdynamik-Aktuatorik (<code>Vlc</code> – Vehicle Longitudinal Control / <code>Esc</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### A. Kapselnde Composition</p>\n<ul class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAcc SW-Composition</code> (<code>CompositionSwComponentType</code>):</strong> Aggregiert fünf atomare Software-Components (<code>ApplicationSwComponentType</code>) zur Abbildung von CC- und ACC-Funktionen.</li>\n</ul>\n<p class=\"fig-p\">#### B. Interne atomare SW-Cs</p>\n<ol class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAccStCtrl</code> (State Control):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verwaltet Betriebsmodi (Off, Standby, Active, Override, Error/Degradation).</li>\n<li>Schnittstellen:</li>\n<li><em>R-Port (Delegation):</em> Anbindung an <code>Multimedia Telematics HMI Domain</code> für Fahrerbedienung (Set, Resume, Target Speed, Time Gap).</li>\n<li><em>R/P-Port (Delegation):</em> Anbindung an <code>Body Electronics Domain</code> zur Abfrage von Systemfreigaben (z. B. ESC-, EPB-Status).</li>\n<li><em>P-Ports (Assembly):</em> Übergabe der Modus-/Statusvorgaben an <code>FolwCtrlAndAArbn</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>AccObjTarSeln</code> (ACC Object Target Selection):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Selektiert und verfolgt das führungsrelevante Zielobjekt (Relevant Target / In-Lane Object).</li>\n<li>Schnittstellen:</li>\n<li><em>R-Port (Assembly/Delegation):</em> Empfang vorverarbeiteter Umfelddaten von <code>SnsrDaProcGen[2]</code> aus dem CDD.</li>\n<li><em>R-Port (Assembly):</em> Empfang kinematischer Ego-Fahrzeugdaten von <code>CrsCtrlAndAccObsvrForVehSt</code>.</li>\n<li><em>P-Port (Assembly):</em> Bereitstellung von Zielobjekt-Trajektorie, Relativgeschwindigkeit ($\\Delta v$) und Distanz ($\\Delta s$) an <code>FolwCtrlAndAArbn</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAccObsvrForVehSt</code> (Observer for Vehicle State):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Filterung und Zustandsschätzung der Fahrzeugkinematik (Geschwindigkeit, Beschleunigung, Gierrate, Nickwinkel).</li>\n<li>Schnittstellen:</li>\n<li><em>R-Port (Delegation):</em> Roh-/Bussignale von <code>Powertrain Domain</code> (Raddrehzahlen, ESC-, EPB-, Antriebsstrang-Rückmeldungen).</li>\n<li><em>P-Ports (Assembly):</em> Verteilung des Ego-Zustands an <code>AccObjTarSeln</code>, <code>CrsCtrlFree</code>, <code>FolwCtrlAndAArbn</code> sowie Rückführung zur Ego-Bewegungskompensation an den <code>SurrndgsSnsr</code> (CDD).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>CrsCtrlFree</code> (Cruise Control Free / Konventioneller Tempomat):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Regelstrecke für reine Geschwindigkeitsregelung ohne Abstandsführung.</li>\n<li>Schnittstellen:</li>\n<li><em>R-Port (Assembly):</em> Ist-Zustand von <code>CrsCtrlAndAccObsvrForVehSt</code>.</li>\n<li><em>P-Port (Assembly):</em> Konventionelle Beschleunigungsanforderung ($a_{\\text{req, CC}}$) an <code>FolwCtrlAndAArbn</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>FolwCtrlAndAArbn</code> (Following Control and Acceleration Arbitration):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abstandsfolgeregelung (Headway Control) und Sollwert-Arbitrierung.</li>\n<li>Arbitriert zwischen Fahrervorgabe, CC-Sollwert (<code>CrsCtrlFree</code>) und ACC-Sollwert (basierend auf <code>AccObjTarSeln</code>).</li>\n<li>Schnittstellen:</li>\n<li><em>P-Port (Delegation):</em> Konsolidierte Beschleunigungs-/Verzögerungsanforderung ($a_{\\text{req}}$, Jerk-Limits) an die externe Komponente <code>Vlc</code> (Vehicle Longitudinal Control).</li>\n</ul>\n<p class=\"fig-p\">#### C. Externe Entitäten & Boundary-Schnittstellen</p>\n<ul class=\"fig-list\">\n<li><strong><code>Multimedia Telematics HMI Domain</code>:</strong> Mensch-Maschine-Schnittstelle für Fahrerbedienung und Parametrierung (ersetzt die frühere Arbeitsgruppenbezeichnung <code>WPII-10.5 (HMI)</code>).</li>\n<li><strong><code>Body Electronics Domain</code>:</strong> Karosserie- und Bremssteuerungs-Signale (<code>Esc</code>, <code>Epb</code>, ....; ersetzt <code>WPII-10.1 (Body)</code>).</li>\n<li><strong><code>Powertrain Domain</code>:</strong> Antriebsstrang- und Raddynamik-Signale (<code>Esc</code>, <code>Epb</code>, ....; ersetzt <code>WPII-10.2 (Powertrain)</code>).</li>\n<li><strong><code>SurrndgsSnsr</code> (Complex Device Driver + Hardware):</strong></li>\n<li>Umfasst physischen <code>Sensor [2]</code> (z. B. Radar/Lidar/Kamera) und BSW-seitigen <code>Complex Device Driver</code> mit Ausprägung <code>SnsrDaProcGen[2]</code> (Generic Sensor Data Processing). Umgeht Standard-BSW-IO-Pfade für echtzeitkritische Punktwolken-/Objektlisten.</li>\n<li><strong><code>Vlc</code> (Vehicle Longitudinal Control) / <code>Esc</code>:</strong></li>\n<li>Unterlagerte Drehmoment- und Bremsdruck-Arbitrierungsinstanz im Fahrwerkspfad zur Ansteuerung der Aktuatoren (ESC-Bremse, Motorsteuerung/Transmission).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Messwertaufnahme & Sensorkompensation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Sensor [2]</code> generiert Rohumfelddaten. Der CDD verarbeitet diese zyklisch (<code>SnsrDaProcGen[2]</code>).</li>\n<li><code>CrsCtrlAndAccObsvrForVehSt</code> liefert zyklisch Ego-Geschwindigkeit und Gierrate an den CDD/Sensor, um stationäre Objekte zu diskriminieren und Ego-Bewegungskompensation durchzuführen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Objektselektion:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>AccObjTarSeln</code> ordnet die vom CDD empfangene Objektliste dem prädizierten Fahrkorridor zu und bestimmt das primäre Regelobjekt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zustands- und Fahrerbedienpfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Fahrerinput über <code>Multimedia Telematics HMI Domain</code> triggert Zustandswechsel in <code>CrsCtrlAndAccStCtrl</code>.</li>\n<li>Bei Aktivierung signalisiert <code>CrsCtrlAndAccStCtrl</code> Freigaben und Betriebsmodi (ACC aktiv vs. CC aktiv) an <code>FolwCtrlAndAArbn</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Regelung & Arbitrierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei freier Fahrt: <code>CrsCtrlFree</code> berechnet die Führungsbeschleunigung zur Zielgeschwindigkeitsregelung.</li>\n<li>Bei Folgezustand: <code>FolwCtrlAndAArbn</code> berechnet über Zielabstand und Relativgeschwindigkeit das Soll-Beschleunigungsprofil zur Abstandsführung.</li>\n<li><code>FolwCtrlAndAArbn</code> arbitriert (Minimum-Auswahl bezüglich Abstands- vs. Tempomatanforderung) und begrenzt Ruck/Gradienten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuierungsübergabe:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der resultierende Beschleunigungswert ($a_{\\text{req}}$) wird zyklisch über den P-Port an <code>Vlc</code> ausgegeben, welches Bremsanforderungen an das <code>Esc</code> bzw. Antriebsmomente an das Motorsteuergerät delegiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Spezifikationsstatus (AUTOSAR_EXP_AIChassis):</strong> Als <em>Explanation</em> (EXP) handelt es sich um eine normative Empfehlung/Referenzarchitektur, nicht um feste SWS-Pflichtanforderungen. Port-Interfaces und Datentypen folgen jedoch den standardisierten AUTOSAR Application Interfaces (Blueprint-Konformität).</li>\n<li><strong>CDD-Einsatz (<code>Complex Device Driver</code>):</strong></li>\n<li>Notwendig, da AUTOSAR bis R4.0.3 keinen standardisierten BSW-Stack für komplexe Umfeldsensorik (Radar-/Kamera-Datenströme, SPI/Ethernet-Rohdaten) bereitstellt.</li>\n<li>Entwickler müssen sicherstellen, dass der CDD die definierten AUTOSAR-Port-Schnittstellen (<code>Sender-Receiver</code>) zur VFB-Schicht (<code>AccObjTarSeln</code>) exakt repliziert.</li>\n<li><strong>Komponentenschnitt:</strong></li>\n<li>Die Trennung von <code>AccObjTarSeln</code> (Objektfilterung) und <code>FolwCtrlAndAArbn</code> (Regelungsarbitrierung) ermöglicht den Sensor-Tausch (z. B. 1x Radar vs. Fusionssensor), ohne die nachgelagerte Fahrzeuglängsdynamik-Regelung anfassen zu müssen.</li>\n<li><strong>RTE- & Task-Allokation:</strong></li>\n<li><code>FolwCtrlAndAArbn</code> und <code>AccObjTarSeln</code> erfordern deterministische Abtastzeiten (typisch: 20–50 ms Task-Periodizität).</li>\n<li><code>CrsCtrlAndAccStCtrl</code> kann in einer niederprioren Zyklustask oder ereignisgesteuert (<code>DataReceivedEvent</code> von HMI) ausgeführt werden.</li>\n<li>Inter-Runnable-Variables (IRV) bzw. RTE-Puffer müssen gegen Dateninkonsistenz geschützt werden (Ego-Fahrzeugstatus muss zeitsynchron zu den Sensordaten im Regelungszyklus vorliegen).</li>\n</ul>"}, {"id": "FIG-cf5e6af36e734bfc", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR VFB-Komponentendiagramm (Internal Architecture View einer <code>CompositionSwComponentType</code> auf Virtual Function Bus-Ebene).</li>\n<li><strong>Technischer Zweck:</strong> Referenzarchitektur der <code>CrsCtrlAndAcc SW-Composition</code> (Cruise Control & Adaptive Cruise Control) bei Anbindung genau eines Umfeldsensors (<code>SurrndgsSnsr</code>) über einen Complex Device Driver (CDD).</li>\n<li><strong>Systemische Einordnung:</strong> Domäne Chassis / Fahrerassistenz (AUTOSAR Chassis Application Interfaces, R4.0.3). Das Diagramm kapselt die Funktionslogik zur Längsregelung (Abstands- und Geschwindigkeitsregelung) zwischen HMI-Bedienung, Sensor-Vorverarbeitung, Fahrzeugzustandsbeobachtung und unterlagerter Längsdynamik-Aktuatorik (<code>Vlc</code> – Vehicle Longitudinal Control / <code>Esc</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### A. Kapselnde Composition</p>\n<ul class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAcc SW-Composition</code> (<code>CompositionSwComponentType</code>):</strong> Aggregiert fünf atomare Software-Components (<code>ApplicationSwComponentType</code>) zur Abbildung von CC- und ACC-Funktionen.</li>\n</ul>\n<p class=\"fig-p\">#### B. Interne atomare SW-Cs</p>\n<ol class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAccStCtrl</code> (State Control):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verwaltet Betriebsmodi (Off, Standby, Active, Override, Error/Degradation).</li>\n<li>Schnittstellen:</li>\n<li><em>R-Port (Delegation):</em> Anbindung an <code>Multimedia Telematics HMI Domain</code> für Fahrerbedienung (Set, Resume, Target Speed, Time Gap).</li>\n<li><em>R/P-Port (Delegation):</em> Anbindung an <code>Body Electronics Domain</code> zur Abfrage von Systemfreigaben (z. B. ESC-, EPB-Status).</li>\n<li><em>P-Ports (Assembly):</em> Übergabe der Modus-/Statusvorgaben an <code>FolwCtrlAndAArbn</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>AccObjTarSeln</code> (ACC Object Target Selection):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Selektiert und verfolgt das führungsrelevante Zielobjekt (Relevant Target / In-Lane Object).</li>\n<li>Schnittstellen:</li>\n<li><em>R-Port (Assembly/Delegation):</em> Empfang vorverarbeiteter Umfelddaten von <code>SnsrDaProcGen[2]</code> aus dem CDD.</li>\n<li><em>R-Port (Assembly):</em> Empfang kinematischer Ego-Fahrzeugdaten von <code>CrsCtrlAndAccObsvrForVehSt</code>.</li>\n<li><em>P-Port (Assembly):</em> Bereitstellung von Zielobjekt-Trajektorie, Relativgeschwindigkeit ($\\Delta v$) und Distanz ($\\Delta s$) an <code>FolwCtrlAndAArbn</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAccObsvrForVehSt</code> (Observer for Vehicle State):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Filterung und Zustandsschätzung der Fahrzeugkinematik (Geschwindigkeit, Beschleunigung, Gierrate, Nickwinkel).</li>\n<li>Schnittstellen:</li>\n<li><em>R-Port (Delegation):</em> Roh-/Bussignale von <code>Powertrain Domain</code> (Raddrehzahlen, ESC-, EPB-, Antriebsstrang-Rückmeldungen).</li>\n<li><em>P-Ports (Assembly):</em> Verteilung des Ego-Zustands an <code>AccObjTarSeln</code>, <code>CrsCtrlFree</code>, <code>FolwCtrlAndAArbn</code> sowie Rückführung zur Ego-Bewegungskompensation an den <code>SurrndgsSnsr</code> (CDD).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>CrsCtrlFree</code> (Cruise Control Free / Konventioneller Tempomat):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Regelstrecke für reine Geschwindigkeitsregelung ohne Abstandsführung.</li>\n<li>Schnittstellen:</li>\n<li><em>R-Port (Assembly):</em> Ist-Zustand von <code>CrsCtrlAndAccObsvrForVehSt</code>.</li>\n<li><em>P-Port (Assembly):</em> Konventionelle Beschleunigungsanforderung ($a_{\\text{req, CC}}$) an <code>FolwCtrlAndAArbn</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>FolwCtrlAndAArbn</code> (Following Control and Acceleration Arbitration):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abstandsfolgeregelung (Headway Control) und Sollwert-Arbitrierung.</li>\n<li>Arbitriert zwischen Fahrervorgabe, CC-Sollwert (<code>CrsCtrlFree</code>) und ACC-Sollwert (basierend auf <code>AccObjTarSeln</code>).</li>\n<li>Schnittstellen:</li>\n<li><em>P-Port (Delegation):</em> Konsolidierte Beschleunigungs-/Verzögerungsanforderung ($a_{\\text{req}}$, Jerk-Limits) an die externe Komponente <code>Vlc</code> (Vehicle Longitudinal Control).</li>\n</ul>\n<p class=\"fig-p\">#### C. Externe Entitäten & Boundary-Schnittstellen</p>\n<ul class=\"fig-list\">\n<li><strong><code>Multimedia Telematics HMI Domain</code>:</strong> Mensch-Maschine-Schnittstelle für Fahrerbedienung und Parametrierung (ersetzt die frühere Arbeitsgruppenbezeichnung <code>WPII-10.5 (HMI)</code>).</li>\n<li><strong><code>Body Electronics Domain</code>:</strong> Karosserie- und Bremssteuerungs-Signale (<code>Esc</code>, <code>Epb</code>, ....; ersetzt <code>WPII-10.1 (Body)</code>).</li>\n<li><strong><code>Powertrain Domain</code>:</strong> Antriebsstrang- und Raddynamik-Signale (<code>Esc</code>, <code>Epb</code>, ....; ersetzt <code>WPII-10.2 (Powertrain)</code>).</li>\n<li><strong><code>SurrndgsSnsr</code> (Complex Device Driver + Hardware):</strong></li>\n<li>Umfasst physischen <code>Sensor [2]</code> (z. B. Radar/Lidar/Kamera) und BSW-seitigen <code>Complex Device Driver</code> mit Ausprägung <code>SnsrDaProcGen[2]</code> (Generic Sensor Data Processing). Umgeht Standard-BSW-IO-Pfade für echtzeitkritische Punktwolken-/Objektlisten.</li>\n<li><strong><code>Vlc</code> (Vehicle Longitudinal Control) / <code>Esc</code>:</strong></li>\n<li>Unterlagerte Drehmoment- und Bremsdruck-Arbitrierungsinstanz im Fahrwerkspfad zur Ansteuerung der Aktuatoren (ESC-Bremse, Motorsteuerung/Transmission).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Messwertaufnahme & Sensorkompensation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Sensor [2]</code> generiert Rohumfelddaten. Der CDD verarbeitet diese zyklisch (<code>SnsrDaProcGen[2]</code>).</li>\n<li><code>CrsCtrlAndAccObsvrForVehSt</code> liefert zyklisch Ego-Geschwindigkeit und Gierrate an den CDD/Sensor, um stationäre Objekte zu diskriminieren und Ego-Bewegungskompensation durchzuführen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Objektselektion:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>AccObjTarSeln</code> ordnet die vom CDD empfangene Objektliste dem prädizierten Fahrkorridor zu und bestimmt das primäre Regelobjekt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zustands- und Fahrerbedienpfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Fahrerinput über <code>Multimedia Telematics HMI Domain</code> triggert Zustandswechsel in <code>CrsCtrlAndAccStCtrl</code>.</li>\n<li>Bei Aktivierung signalisiert <code>CrsCtrlAndAccStCtrl</code> Freigaben und Betriebsmodi (ACC aktiv vs. CC aktiv) an <code>FolwCtrlAndAArbn</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Regelung & Arbitrierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei freier Fahrt: <code>CrsCtrlFree</code> berechnet die Führungsbeschleunigung zur Zielgeschwindigkeitsregelung.</li>\n<li>Bei Folgezustand: <code>FolwCtrlAndAArbn</code> berechnet über Zielabstand und Relativgeschwindigkeit das Soll-Beschleunigungsprofil zur Abstandsführung.</li>\n<li><code>FolwCtrlAndAArbn</code> arbitriert (Minimum-Auswahl bezüglich Abstands- vs. Tempomatanforderung) und begrenzt Ruck/Gradienten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuierungsübergabe:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der resultierende Beschleunigungswert ($a_{\\text{req}}$) wird zyklisch über den P-Port an <code>Vlc</code> ausgegeben, welches Bremsanforderungen an das <code>Esc</code> bzw. Antriebsmomente an das Motorsteuergerät delegiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Spezifikationsstatus (AUTOSAR_EXP_AIChassis):</strong> Als <em>Explanation</em> (EXP) handelt es sich um eine normative Empfehlung/Referenzarchitektur, nicht um feste SWS-Pflichtanforderungen. Port-Interfaces und Datentypen folgen jedoch den standardisierten AUTOSAR Application Interfaces (Blueprint-Konformität).</li>\n<li><strong>CDD-Einsatz (<code>Complex Device Driver</code>):</strong></li>\n<li>Notwendig, da AUTOSAR bis R4.0.3 keinen standardisierten BSW-Stack für komplexe Umfeldsensorik (Radar-/Kamera-Datenströme, SPI/Ethernet-Rohdaten) bereitstellt.</li>\n<li>Entwickler müssen sicherstellen, dass der CDD die definierten AUTOSAR-Port-Schnittstellen (<code>Sender-Receiver</code>) zur VFB-Schicht (<code>AccObjTarSeln</code>) exakt repliziert.</li>\n<li><strong>Komponentenschnitt:</strong></li>\n<li>Die Trennung von <code>AccObjTarSeln</code> (Objektfilterung) und <code>FolwCtrlAndAArbn</code> (Regelungsarbitrierung) ermöglicht den Sensor-Tausch (z. B. 1x Radar vs. Fusionssensor), ohne die nachgelagerte Fahrzeuglängsdynamik-Regelung anfassen zu müssen.</li>\n<li><strong>RTE- & Task-Allokation:</strong></li>\n<li><code>FolwCtrlAndAArbn</code> und <code>AccObjTarSeln</code> erfordern deterministische Abtastzeiten (typisch: 20–50 ms Task-Periodizität).</li>\n<li><code>CrsCtrlAndAccStCtrl</code> kann in einer niederprioren Zyklustask oder ereignisgesteuert (<code>DataReceivedEvent</code> von HMI) ausgeführt werden.</li>\n<li>Inter-Runnable-Variables (IRV) bzw. RTE-Puffer müssen gegen Dateninkonsistenz geschützt werden (Ego-Fahrzeugstatus muss zeitsynchron zu den Sensordaten im Regelungszyklus vorliegen).</li>\n</ul>"}, {"id": "FIG-1ca3b1ade4a0a11e", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR VFB-Komponentendiagramm (Internal Architecture View einer <code>CompositionSwComponentType</code> auf Virtual Function Bus-Ebene).</li>\n<li><strong>Technischer Zweck:</strong> Referenzarchitektur der <code>CrsCtrlAndAcc SW-Composition</code> (Cruise Control & Adaptive Cruise Control) bei Anbindung genau eines Umfeldsensors (<code>SurrndgsSnsr</code>) über einen Complex Device Driver (CDD).</li>\n<li><strong>Systemische Einordnung:</strong> Domäne Chassis / Fahrerassistenz (AUTOSAR Chassis Application Interfaces, R4.0.3). Das Diagramm kapselt die Funktionslogik zur Längsregelung (Abstands- und Geschwindigkeitsregelung) zwischen HMI-Bedienung, Sensor-Vorverarbeitung, Fahrzeugzustandsbeobachtung und unterlagerter Längsdynamik-Aktuatorik (<code>Vlc</code> – Vehicle Longitudinal Control / <code>Esc</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### A. Kapselnde Composition</p>\n<ul class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAcc SW-Composition</code> (<code>CompositionSwComponentType</code>):</strong> Aggregiert fünf atomare Software-Components (<code>ApplicationSwComponentType</code>) zur Abbildung von CC- und ACC-Funktionen.</li>\n</ul>\n<p class=\"fig-p\">#### B. Interne atomare SW-Cs</p>\n<ol class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAccStCtrl</code> (State Control):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verwaltet Betriebsmodi (Off, Standby, Active, Override, Error/Degradation).</li>\n<li>Schnittstellen:</li>\n<li><em>R-Port (Delegation):</em> Anbindung an <code>Multimedia Telematics HMI Domain</code> für Fahrerbedienung (Set, Resume, Target Speed, Time Gap).</li>\n<li><em>R/P-Port (Delegation):</em> Anbindung an <code>Body Electronics Domain</code> zur Abfrage von Systemfreigaben (z. B. ESC-, EPB-Status).</li>\n<li><em>P-Ports (Assembly):</em> Übergabe der Modus-/Statusvorgaben an <code>FolwCtrlAndAArbn</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>AccObjTarSeln</code> (ACC Object Target Selection):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Selektiert und verfolgt das führungsrelevante Zielobjekt (Relevant Target / In-Lane Object).</li>\n<li>Schnittstellen:</li>\n<li><em>R-Port (Assembly/Delegation):</em> Empfang vorverarbeiteter Umfelddaten von <code>SnsrDaProcGen[2]</code> aus dem CDD.</li>\n<li><em>R-Port (Assembly):</em> Empfang kinematischer Ego-Fahrzeugdaten von <code>CrsCtrlAndAccObsvrForVehSt</code>.</li>\n<li><em>P-Port (Assembly):</em> Bereitstellung von Zielobjekt-Trajektorie, Relativgeschwindigkeit ($\\Delta v$) und Distanz ($\\Delta s$) an <code>FolwCtrlAndAArbn</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAccObsvrForVehSt</code> (Observer for Vehicle State):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Filterung und Zustandsschätzung der Fahrzeugkinematik (Geschwindigkeit, Beschleunigung, Gierrate, Nickwinkel).</li>\n<li>Schnittstellen:</li>\n<li><em>R-Port (Delegation):</em> Roh-/Bussignale von <code>Powertrain Domain</code> (Raddrehzahlen, ESC-, EPB-, Antriebsstrang-Rückmeldungen).</li>\n<li><em>P-Ports (Assembly):</em> Verteilung des Ego-Zustands an <code>AccObjTarSeln</code>, <code>CrsCtrlFree</code>, <code>FolwCtrlAndAArbn</code> sowie Rückführung zur Ego-Bewegungskompensation an den <code>SurrndgsSnsr</code> (CDD).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>CrsCtrlFree</code> (Cruise Control Free / Konventioneller Tempomat):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Regelstrecke für reine Geschwindigkeitsregelung ohne Abstandsführung.</li>\n<li>Schnittstellen:</li>\n<li><em>R-Port (Assembly):</em> Ist-Zustand von <code>CrsCtrlAndAccObsvrForVehSt</code>.</li>\n<li><em>P-Port (Assembly):</em> Konventionelle Beschleunigungsanforderung ($a_{\\text{req, CC}}$) an <code>FolwCtrlAndAArbn</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>FolwCtrlAndAArbn</code> (Following Control and Acceleration Arbitration):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abstandsfolgeregelung (Headway Control) und Sollwert-Arbitrierung.</li>\n<li>Arbitriert zwischen Fahrervorgabe, CC-Sollwert (<code>CrsCtrlFree</code>) und ACC-Sollwert (basierend auf <code>AccObjTarSeln</code>).</li>\n<li>Schnittstellen:</li>\n<li><em>P-Port (Delegation):</em> Konsolidierte Beschleunigungs-/Verzögerungsanforderung ($a_{\\text{req}}$, Jerk-Limits) an die externe Komponente <code>Vlc</code> (Vehicle Longitudinal Control).</li>\n</ul>\n<p class=\"fig-p\">#### C. Externe Entitäten & Boundary-Schnittstellen</p>\n<ul class=\"fig-list\">\n<li><strong><code>Multimedia Telematics HMI Domain</code>:</strong> Mensch-Maschine-Schnittstelle für Fahrerbedienung und Parametrierung (ersetzt die frühere Arbeitsgruppenbezeichnung <code>WPII-10.5 (HMI)</code>).</li>\n<li><strong><code>Body Electronics Domain</code>:</strong> Karosserie- und Bremssteuerungs-Signale (<code>Esc</code>, <code>Epb</code>, ....; ersetzt <code>WPII-10.1 (Body)</code>).</li>\n<li><strong><code>Powertrain Domain</code>:</strong> Antriebsstrang- und Raddynamik-Signale (<code>Esc</code>, <code>Epb</code>, ....; ersetzt <code>WPII-10.2 (Powertrain)</code>).</li>\n<li><strong><code>SurrndgsSnsr</code> (Complex Device Driver + Hardware):</strong></li>\n<li>Umfasst physischen <code>Sensor [2]</code> (z. B. Radar/Lidar/Kamera) und BSW-seitigen <code>Complex Device Driver</code> mit Ausprägung <code>SnsrDaProcGen[2]</code> (Generic Sensor Data Processing). Umgeht Standard-BSW-IO-Pfade für echtzeitkritische Punktwolken-/Objektlisten.</li>\n<li><strong><code>Vlc</code> (Vehicle Longitudinal Control) / <code>Esc</code>:</strong></li>\n<li>Unterlagerte Drehmoment- und Bremsdruck-Arbitrierungsinstanz im Fahrwerkspfad zur Ansteuerung der Aktuatoren (ESC-Bremse, Motorsteuerung/Transmission).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Messwertaufnahme & Sensorkompensation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Sensor [2]</code> generiert Rohumfelddaten. Der CDD verarbeitet diese zyklisch (<code>SnsrDaProcGen[2]</code>).</li>\n<li><code>CrsCtrlAndAccObsvrForVehSt</code> liefert zyklisch Ego-Geschwindigkeit und Gierrate an den CDD/Sensor, um stationäre Objekte zu diskriminieren und Ego-Bewegungskompensation durchzuführen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Objektselektion:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>AccObjTarSeln</code> ordnet die vom CDD empfangene Objektliste dem prädizierten Fahrkorridor zu und bestimmt das primäre Regelobjekt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zustands- und Fahrerbedienpfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Fahrerinput über <code>Multimedia Telematics HMI Domain</code> triggert Zustandswechsel in <code>CrsCtrlAndAccStCtrl</code>.</li>\n<li>Bei Aktivierung signalisiert <code>CrsCtrlAndAccStCtrl</code> Freigaben und Betriebsmodi (ACC aktiv vs. CC aktiv) an <code>FolwCtrlAndAArbn</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Regelung & Arbitrierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei freier Fahrt: <code>CrsCtrlFree</code> berechnet die Führungsbeschleunigung zur Zielgeschwindigkeitsregelung.</li>\n<li>Bei Folgezustand: <code>FolwCtrlAndAArbn</code> berechnet über Zielabstand und Relativgeschwindigkeit das Soll-Beschleunigungsprofil zur Abstandsführung.</li>\n<li><code>FolwCtrlAndAArbn</code> arbitriert (Minimum-Auswahl bezüglich Abstands- vs. Tempomatanforderung) und begrenzt Ruck/Gradienten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuierungsübergabe:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der resultierende Beschleunigungswert ($a_{\\text{req}}$) wird zyklisch über den P-Port an <code>Vlc</code> ausgegeben, welches Bremsanforderungen an das <code>Esc</code> bzw. Antriebsmomente an das Motorsteuergerät delegiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Spezifikationsstatus (AUTOSAR_EXP_AIChassis):</strong> Als <em>Explanation</em> (EXP) handelt es sich um eine normative Empfehlung/Referenzarchitektur, nicht um feste SWS-Pflichtanforderungen. Port-Interfaces und Datentypen folgen jedoch den standardisierten AUTOSAR Application Interfaces (Blueprint-Konformität).</li>\n<li><strong>CDD-Einsatz (<code>Complex Device Driver</code>):</strong></li>\n<li>Notwendig, da AUTOSAR bis R4.0.3 keinen standardisierten BSW-Stack für komplexe Umfeldsensorik (Radar-/Kamera-Datenströme, SPI/Ethernet-Rohdaten) bereitstellt.</li>\n<li>Entwickler müssen sicherstellen, dass der CDD die definierten AUTOSAR-Port-Schnittstellen (<code>Sender-Receiver</code>) zur VFB-Schicht (<code>AccObjTarSeln</code>) exakt repliziert.</li>\n<li><strong>Komponentenschnitt:</strong></li>\n<li>Die Trennung von <code>AccObjTarSeln</code> (Objektfilterung) und <code>FolwCtrlAndAArbn</code> (Regelungsarbitrierung) ermöglicht den Sensor-Tausch (z. B. 1x Radar vs. Fusionssensor), ohne die nachgelagerte Fahrzeuglängsdynamik-Regelung anfassen zu müssen.</li>\n<li><strong>RTE- & Task-Allokation:</strong></li>\n<li><code>FolwCtrlAndAArbn</code> und <code>AccObjTarSeln</code> erfordern deterministische Abtastzeiten (typisch: 20–50 ms Task-Periodizität).</li>\n<li><code>CrsCtrlAndAccStCtrl</code> kann in einer niederprioren Zyklustask oder ereignisgesteuert (<code>DataReceivedEvent</code> von HMI) ausgeführt werden.</li>\n<li>Inter-Runnable-Variables (IRV) bzw. RTE-Puffer müssen gegen Dateninkonsistenz geschützt werden (Ego-Fahrzeugstatus muss zeitsynchron zu den Sensordaten im Regelungszyklus vorliegen).</li>\n</ul>"}, {"id": "FIG-47b7aac5fa98330e", "releases": ["R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR VFB-Komponentendiagramm (Internal Architecture View einer <code>CompositionSwComponentType</code> auf Virtual Function Bus-Ebene).</li>\n<li><strong>Technischer Zweck:</strong> Referenzarchitektur der <code>CrsCtrlAndAcc SW-Composition</code> (Cruise Control & Adaptive Cruise Control) bei Anbindung genau eines Umfeldsensors (<code>SurrndgsSnsr</code>) über einen Complex Device Driver (CDD).</li>\n<li><strong>Systemische Einordnung:</strong> Domäne Chassis / Fahrerassistenz (AUTOSAR Chassis Application Interfaces, R4.0.3). Das Diagramm kapselt die Funktionslogik zur Längsregelung (Abstands- und Geschwindigkeitsregelung) zwischen HMI-Bedienung, Sensor-Vorverarbeitung, Fahrzeugzustandsbeobachtung und unterlagerter Längsdynamik-Aktuatorik (<code>Vlc</code> – Vehicle Longitudinal Control / <code>Esc</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### A. Kapselnde Composition</p>\n<ul class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAcc SW-Composition</code> (<code>CompositionSwComponentType</code>):</strong> Aggregiert fünf atomare Software-Components (<code>ApplicationSwComponentType</code>) zur Abbildung von CC- und ACC-Funktionen.</li>\n</ul>\n<p class=\"fig-p\">#### B. Interne atomare SW-Cs</p>\n<ol class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAccStCtrl</code> (State Control):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verwaltet Betriebsmodi (Off, Standby, Active, Override, Error/Degradation).</li>\n<li>Schnittstellen:</li>\n<li><em>R-Port (Delegation):</em> Anbindung an <code>Multimedia Telematics HMI Domain</code> für Fahrerbedienung (Set, Resume, Target Speed, Time Gap).</li>\n<li><em>R/P-Port (Delegation):</em> Anbindung an <code>Body Electronics Domain</code> zur Abfrage von Systemfreigaben (z. B. ESC-, EPB-Status).</li>\n<li><em>P-Ports (Assembly):</em> Übergabe der Modus-/Statusvorgaben an <code>FolwCtrlAndAArbn</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>AccObjTarSeln</code> (ACC Object Target Selection):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Selektiert und verfolgt das führungsrelevante Zielobjekt (Relevant Target / In-Lane Object).</li>\n<li>Schnittstellen:</li>\n<li><em>R-Port (Assembly/Delegation):</em> Empfang vorverarbeiteter Umfelddaten von <code>SnsrDaProcGen[2]</code> aus dem CDD.</li>\n<li><em>R-Port (Assembly):</em> Empfang kinematischer Ego-Fahrzeugdaten von <code>CrsCtrlAndAccObsvrForVehSt</code>.</li>\n<li><em>P-Port (Assembly):</em> Bereitstellung von Zielobjekt-Trajektorie, Relativgeschwindigkeit ($\\Delta v$) und Distanz ($\\Delta s$) an <code>FolwCtrlAndAArbn</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAccObsvrForVehSt</code> (Observer for Vehicle State):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Filterung und Zustandsschätzung der Fahrzeugkinematik (Geschwindigkeit, Beschleunigung, Gierrate, Nickwinkel).</li>\n<li>Schnittstellen:</li>\n<li><em>R-Port (Delegation):</em> Roh-/Bussignale von <code>Powertrain Domain</code> (Raddrehzahlen, ESC-, EPB-, Antriebsstrang-Rückmeldungen).</li>\n<li><em>P-Ports (Assembly):</em> Verteilung des Ego-Zustands an <code>AccObjTarSeln</code>, <code>CrsCtrlFree</code>, <code>FolwCtrlAndAArbn</code> sowie Rückführung zur Ego-Bewegungskompensation an den <code>SurrndgsSnsr</code> (CDD).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>CrsCtrlFree</code> (Cruise Control Free / Konventioneller Tempomat):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Regelstrecke für reine Geschwindigkeitsregelung ohne Abstandsführung.</li>\n<li>Schnittstellen:</li>\n<li><em>R-Port (Assembly):</em> Ist-Zustand von <code>CrsCtrlAndAccObsvrForVehSt</code>.</li>\n<li><em>P-Port (Assembly):</em> Konventionelle Beschleunigungsanforderung ($a_{\\text{req, CC}}$) an <code>FolwCtrlAndAArbn</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>FolwCtrlAndAArbn</code> (Following Control and Acceleration Arbitration):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abstandsfolgeregelung (Headway Control) und Sollwert-Arbitrierung.</li>\n<li>Arbitriert zwischen Fahrervorgabe, CC-Sollwert (<code>CrsCtrlFree</code>) und ACC-Sollwert (basierend auf <code>AccObjTarSeln</code>).</li>\n<li>Schnittstellen:</li>\n<li><em>P-Port (Delegation):</em> Konsolidierte Beschleunigungs-/Verzögerungsanforderung ($a_{\\text{req}}$, Jerk-Limits) an die externe Komponente <code>Vlc</code> (Vehicle Longitudinal Control).</li>\n</ul>\n<p class=\"fig-p\">#### C. Externe Entitäten & Boundary-Schnittstellen</p>\n<ul class=\"fig-list\">\n<li><strong><code>Multimedia Telematics HMI Domain</code>:</strong> Mensch-Maschine-Schnittstelle für Fahrerbedienung und Parametrierung (ersetzt die frühere Arbeitsgruppenbezeichnung <code>WPII-10.5 (HMI)</code>).</li>\n<li><strong><code>Body Electronics Domain</code>:</strong> Karosserie- und Bremssteuerungs-Signale (<code>Esc</code>, <code>Epb</code>, ....; ersetzt <code>WPII-10.1 (Body)</code>).</li>\n<li><strong><code>Powertrain Domain</code>:</strong> Antriebsstrang- und Raddynamik-Signale (<code>Esc</code>, <code>Epb</code>, ....; ersetzt <code>WPII-10.2 (Powertrain)</code>).</li>\n<li><strong><code>SurrndgsSnsr</code> (Complex Device Driver + Hardware):</strong></li>\n<li>Umfasst physischen <code>Sensor [2]</code> (z. B. Radar/Lidar/Kamera) und BSW-seitigen <code>Complex Device Driver</code> mit Ausprägung <code>SnsrDaProcGen[2]</code> (Generic Sensor Data Processing). Umgeht Standard-BSW-IO-Pfade für echtzeitkritische Punktwolken-/Objektlisten.</li>\n<li><strong><code>Vlc</code> (Vehicle Longitudinal Control) / <code>Esc</code>:</strong></li>\n<li>Unterlagerte Drehmoment- und Bremsdruck-Arbitrierungsinstanz im Fahrwerkspfad zur Ansteuerung der Aktuatoren (ESC-Bremse, Motorsteuerung/Transmission).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Messwertaufnahme & Sensorkompensation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Sensor [2]</code> generiert Rohumfelddaten. Der CDD verarbeitet diese zyklisch (<code>SnsrDaProcGen[2]</code>).</li>\n<li><code>CrsCtrlAndAccObsvrForVehSt</code> liefert zyklisch Ego-Geschwindigkeit und Gierrate an den CDD/Sensor, um stationäre Objekte zu diskriminieren und Ego-Bewegungskompensation durchzuführen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Objektselektion:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>AccObjTarSeln</code> ordnet die vom CDD empfangene Objektliste dem prädizierten Fahrkorridor zu und bestimmt das primäre Regelobjekt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zustands- und Fahrerbedienpfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Fahrerinput über <code>Multimedia Telematics HMI Domain</code> triggert Zustandswechsel in <code>CrsCtrlAndAccStCtrl</code>.</li>\n<li>Bei Aktivierung signalisiert <code>CrsCtrlAndAccStCtrl</code> Freigaben und Betriebsmodi (ACC aktiv vs. CC aktiv) an <code>FolwCtrlAndAArbn</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Regelung & Arbitrierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei freier Fahrt: <code>CrsCtrlFree</code> berechnet die Führungsbeschleunigung zur Zielgeschwindigkeitsregelung.</li>\n<li>Bei Folgezustand: <code>FolwCtrlAndAArbn</code> berechnet über Zielabstand und Relativgeschwindigkeit das Soll-Beschleunigungsprofil zur Abstandsführung.</li>\n<li><code>FolwCtrlAndAArbn</code> arbitriert (Minimum-Auswahl bezüglich Abstands- vs. Tempomatanforderung) und begrenzt Ruck/Gradienten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuierungsübergabe:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der resultierende Beschleunigungswert ($a_{\\text{req}}$) wird zyklisch über den P-Port an <code>Vlc</code> ausgegeben, welches Bremsanforderungen an das <code>Esc</code> bzw. Antriebsmomente an das Motorsteuergerät delegiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Spezifikationsstatus (AUTOSAR_EXP_AIChassis):</strong> Als <em>Explanation</em> (EXP) handelt es sich um eine normative Empfehlung/Referenzarchitektur, nicht um feste SWS-Pflichtanforderungen. Port-Interfaces und Datentypen folgen jedoch den standardisierten AUTOSAR Application Interfaces (Blueprint-Konformität).</li>\n<li><strong>CDD-Einsatz (<code>Complex Device Driver</code>):</strong></li>\n<li>Notwendig, da AUTOSAR bis R4.0.3 keinen standardisierten BSW-Stack für komplexe Umfeldsensorik (Radar-/Kamera-Datenströme, SPI/Ethernet-Rohdaten) bereitstellt.</li>\n<li>Entwickler müssen sicherstellen, dass der CDD die definierten AUTOSAR-Port-Schnittstellen (<code>Sender-Receiver</code>) zur VFB-Schicht (<code>AccObjTarSeln</code>) exakt repliziert.</li>\n<li><strong>Komponentenschnitt:</strong></li>\n<li>Die Trennung von <code>AccObjTarSeln</code> (Objektfilterung) und <code>FolwCtrlAndAArbn</code> (Regelungsarbitrierung) ermöglicht den Sensor-Tausch (z. B. 1x Radar vs. Fusionssensor), ohne die nachgelagerte Fahrzeuglängsdynamik-Regelung anfassen zu müssen.</li>\n<li><strong>RTE- & Task-Allokation:</strong></li>\n<li><code>FolwCtrlAndAArbn</code> und <code>AccObjTarSeln</code> erfordern deterministische Abtastzeiten (typisch: 20–50 ms Task-Periodizität).</li>\n<li><code>CrsCtrlAndAccStCtrl</code> kann in einer niederprioren Zyklustask oder ereignisgesteuert (<code>DataReceivedEvent</code> von HMI) ausgeführt werden.</li>\n<li>Inter-Runnable-Variables (IRV) bzw. RTE-Puffer müssen gegen Dateninkonsistenz geschützt werden (Ego-Fahrzeugstatus muss zeitsynchron zu den Sensordaten im Regelungszyklus vorliegen).</li>\n</ul>"}, {"id": "FIG-441e9da87922bf50", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR VFB-Komponentendiagramm (Internal Architecture View einer <code>CompositionSwComponentType</code> auf Virtual Function Bus-Ebene).</li>\n<li><strong>Technischer Zweck:</strong> Referenzarchitektur der <code>CrsCtrlAndAcc SW-Composition</code> (Cruise Control & Adaptive Cruise Control) bei Anbindung genau eines Umfeldsensors (<code>SurrndgsSnsr</code>) über einen Complex Device Driver (CDD).</li>\n<li><strong>Systemische Einordnung:</strong> Domäne Chassis / Fahrerassistenz (AUTOSAR Chassis Application Interfaces, R4.0.3). Das Diagramm kapselt die Funktionslogik zur Längsregelung (Abstands- und Geschwindigkeitsregelung) zwischen HMI-Bedienung, Sensor-Vorverarbeitung, Fahrzeugzustandsbeobachtung und unterlagerter Längsdynamik-Aktuatorik (<code>Vlc</code> – Vehicle Longitudinal Control / <code>Esc</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### A. Kapselnde Composition</p>\n<ul class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAcc SW-Composition</code> (<code>CompositionSwComponentType</code>):</strong> Aggregiert fünf atomare Software-Components (<code>ApplicationSwComponentType</code>) zur Abbildung von CC- und ACC-Funktionen.</li>\n</ul>\n<p class=\"fig-p\">#### B. Interne atomare SW-Cs</p>\n<ol class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAccStCtrl</code> (State Control):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verwaltet Betriebsmodi (Off, Standby, Active, Override, Error/Degradation).</li>\n<li>Schnittstellen:</li>\n<li><em>R-Port (Delegation):</em> Anbindung an <code>Multimedia Telematics HMI Domain</code> für Fahrerbedienung (Set, Resume, Target Speed, Time Gap).</li>\n<li><em>R/P-Port (Delegation):</em> Anbindung an <code>Body Electronics Domain</code> zur Abfrage von Systemfreigaben (z. B. ESC-, EPB-Status).</li>\n<li><em>P-Ports (Assembly):</em> Übergabe der Modus-/Statusvorgaben an <code>FolwCtrlAndAArbn</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>AccObjTarSeln</code> (ACC Object Target Selection):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Selektiert und verfolgt das führungsrelevante Zielobjekt (Relevant Target / In-Lane Object).</li>\n<li>Schnittstellen:</li>\n<li><em>R-Port (Assembly/Delegation):</em> Empfang vorverarbeiteter Umfelddaten von <code>SnsrDaProcGen[2]</code> aus dem CDD.</li>\n<li><em>R-Port (Assembly):</em> Empfang kinematischer Ego-Fahrzeugdaten von <code>CrsCtrlAndAccObsvrForVehSt</code>.</li>\n<li><em>P-Port (Assembly):</em> Bereitstellung von Zielobjekt-Trajektorie, Relativgeschwindigkeit ($\\Delta v$) und Distanz ($\\Delta s$) an <code>FolwCtrlAndAArbn</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAccObsvrForVehSt</code> (Observer for Vehicle State):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Filterung und Zustandsschätzung der Fahrzeugkinematik (Geschwindigkeit, Beschleunigung, Gierrate, Nickwinkel).</li>\n<li>Schnittstellen:</li>\n<li><em>R-Port (Delegation):</em> Roh-/Bussignale von <code>Powertrain Domain</code> (Raddrehzahlen, ESC-, EPB-, Antriebsstrang-Rückmeldungen).</li>\n<li><em>P-Ports (Assembly):</em> Verteilung des Ego-Zustands an <code>AccObjTarSeln</code>, <code>CrsCtrlFree</code>, <code>FolwCtrlAndAArbn</code> sowie Rückführung zur Ego-Bewegungskompensation an den <code>SurrndgsSnsr</code> (CDD).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>CrsCtrlFree</code> (Cruise Control Free / Konventioneller Tempomat):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Regelstrecke für reine Geschwindigkeitsregelung ohne Abstandsführung.</li>\n<li>Schnittstellen:</li>\n<li><em>R-Port (Assembly):</em> Ist-Zustand von <code>CrsCtrlAndAccObsvrForVehSt</code>.</li>\n<li><em>P-Port (Assembly):</em> Konventionelle Beschleunigungsanforderung ($a_{\\text{req, CC}}$) an <code>FolwCtrlAndAArbn</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>FolwCtrlAndAArbn</code> (Following Control and Acceleration Arbitration):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abstandsfolgeregelung (Headway Control) und Sollwert-Arbitrierung.</li>\n<li>Arbitriert zwischen Fahrervorgabe, CC-Sollwert (<code>CrsCtrlFree</code>) und ACC-Sollwert (basierend auf <code>AccObjTarSeln</code>).</li>\n<li>Schnittstellen:</li>\n<li><em>P-Port (Delegation):</em> Konsolidierte Beschleunigungs-/Verzögerungsanforderung ($a_{\\text{req}}$, Jerk-Limits) an die externe Komponente <code>Vlc</code> (Vehicle Longitudinal Control).</li>\n</ul>\n<p class=\"fig-p\">#### C. Externe Entitäten & Boundary-Schnittstellen</p>\n<ul class=\"fig-list\">\n<li><strong><code>Multimedia Telematics HMI Domain</code>:</strong> Mensch-Maschine-Schnittstelle für Fahrerbedienung und Parametrierung (ersetzt die frühere Arbeitsgruppenbezeichnung <code>WPII-10.5 (HMI)</code>).</li>\n<li><strong><code>Body Electronics Domain</code>:</strong> Karosserie- und Bremssteuerungs-Signale (<code>Esc</code>, <code>Epb</code>, ....; ersetzt <code>WPII-10.1 (Body)</code>).</li>\n<li><strong><code>Powertrain Domain</code>:</strong> Antriebsstrang- und Raddynamik-Signale (<code>Esc</code>, <code>Epb</code>, ....; ersetzt <code>WPII-10.2 (Powertrain)</code>).</li>\n<li><strong><code>SurrndgsSnsr</code> (Complex Device Driver + Hardware):</strong></li>\n<li>Umfasst physischen <code>Sensor [2]</code> (z. B. Radar/Lidar/Kamera) und BSW-seitigen <code>Complex Device Driver</code> mit Ausprägung <code>SnsrDaProcGen[2]</code> (Generic Sensor Data Processing). Umgeht Standard-BSW-IO-Pfade für echtzeitkritische Punktwolken-/Objektlisten.</li>\n<li><strong><code>Vlc</code> (Vehicle Longitudinal Control) / <code>Esc</code>:</strong></li>\n<li>Unterlagerte Drehmoment- und Bremsdruck-Arbitrierungsinstanz im Fahrwerkspfad zur Ansteuerung der Aktuatoren (ESC-Bremse, Motorsteuerung/Transmission).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Messwertaufnahme & Sensorkompensation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Sensor [2]</code> generiert Rohumfelddaten. Der CDD verarbeitet diese zyklisch (<code>SnsrDaProcGen[2]</code>).</li>\n<li><code>CrsCtrlAndAccObsvrForVehSt</code> liefert zyklisch Ego-Geschwindigkeit und Gierrate an den CDD/Sensor, um stationäre Objekte zu diskriminieren und Ego-Bewegungskompensation durchzuführen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Objektselektion:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>AccObjTarSeln</code> ordnet die vom CDD empfangene Objektliste dem prädizierten Fahrkorridor zu und bestimmt das primäre Regelobjekt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zustands- und Fahrerbedienpfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Fahrerinput über <code>Multimedia Telematics HMI Domain</code> triggert Zustandswechsel in <code>CrsCtrlAndAccStCtrl</code>.</li>\n<li>Bei Aktivierung signalisiert <code>CrsCtrlAndAccStCtrl</code> Freigaben und Betriebsmodi (ACC aktiv vs. CC aktiv) an <code>FolwCtrlAndAArbn</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Regelung & Arbitrierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei freier Fahrt: <code>CrsCtrlFree</code> berechnet die Führungsbeschleunigung zur Zielgeschwindigkeitsregelung.</li>\n<li>Bei Folgezustand: <code>FolwCtrlAndAArbn</code> berechnet über Zielabstand und Relativgeschwindigkeit das Soll-Beschleunigungsprofil zur Abstandsführung.</li>\n<li><code>FolwCtrlAndAArbn</code> arbitriert (Minimum-Auswahl bezüglich Abstands- vs. Tempomatanforderung) und begrenzt Ruck/Gradienten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuierungsübergabe:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der resultierende Beschleunigungswert ($a_{\\text{req}}$) wird zyklisch über den P-Port an <code>Vlc</code> ausgegeben, welches Bremsanforderungen an das <code>Esc</code> bzw. Antriebsmomente an das Motorsteuergerät delegiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Spezifikationsstatus (AUTOSAR_EXP_AIChassis):</strong> Als <em>Explanation</em> (EXP) handelt es sich um eine normative Empfehlung/Referenzarchitektur, nicht um feste SWS-Pflichtanforderungen. Port-Interfaces und Datentypen folgen jedoch den standardisierten AUTOSAR Application Interfaces (Blueprint-Konformität).</li>\n<li><strong>CDD-Einsatz (<code>Complex Device Driver</code>):</strong></li>\n<li>Notwendig, da AUTOSAR bis R4.0.3 keinen standardisierten BSW-Stack für komplexe Umfeldsensorik (Radar-/Kamera-Datenströme, SPI/Ethernet-Rohdaten) bereitstellt.</li>\n<li>Entwickler müssen sicherstellen, dass der CDD die definierten AUTOSAR-Port-Schnittstellen (<code>Sender-Receiver</code>) zur VFB-Schicht (<code>AccObjTarSeln</code>) exakt repliziert.</li>\n<li><strong>Komponentenschnitt:</strong></li>\n<li>Die Trennung von <code>AccObjTarSeln</code> (Objektfilterung) und <code>FolwCtrlAndAArbn</code> (Regelungsarbitrierung) ermöglicht den Sensor-Tausch (z. B. 1x Radar vs. Fusionssensor), ohne die nachgelagerte Fahrzeuglängsdynamik-Regelung anfassen zu müssen.</li>\n<li><strong>RTE- & Task-Allokation:</strong></li>\n<li><code>FolwCtrlAndAArbn</code> und <code>AccObjTarSeln</code> erfordern deterministische Abtastzeiten (typisch: 20–50 ms Task-Periodizität).</li>\n<li><code>CrsCtrlAndAccStCtrl</code> kann in einer niederprioren Zyklustask oder ereignisgesteuert (<code>DataReceivedEvent</code> von HMI) ausgeführt werden.</li>\n<li>Inter-Runnable-Variables (IRV) bzw. RTE-Puffer müssen gegen Dateninkonsistenz geschützt werden (Ego-Fahrzeugstatus muss zeitsynchron zu den Sensordaten im Regelungszyklus vorliegen).</li>\n</ul>"}], "trans": [{"from": "FIG-04d80faafd746a43", "to": "FIG-37b13293d309d942", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>Multimedia Telematics HMI Domain</code>: Umbenennung des externen Schnittstellenblocks von <code>WPII-10.5 (HMI)</code>.</li>\n<li><code>Body Electronics Domain</code>: Umbenennung des externen Schnittstellenblocks von <code>WPII-10.1 (Body)</code>.</li>\n<li><code>Powertrain Domain</code>: Umbenennung des externen Schnittstellenblocks von <code>WPII-10.2 (Powertrain)</code>.</li>\n<li>Layout: Vergrößerung des unteren Bildausschnitts, sodass die Fortsetzungspunkte (<code>....</code>) unterhalb von <code>Epb</code> am rechten unteren Rand vollständig sichtbar sind.</li>\n</ul>"}, {"from": "FIG-37b13293d309d942", "to": "FIG-cf5e6af36e734bfc", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-cf5e6af36e734bfc", "to": "FIG-1ca3b1ade4a0a11e", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-1ca3b1ade4a0a11e", "to": "FIG-47b7aac5fa98330e", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-47b7aac5fa98330e", "to": "FIG-441e9da87922bf50", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
